"""Build the final acceptance ledger from recorded evidence, with explicit gaps."""
from pathlib import Path
import datetime
import json
import subprocess

P=Path(__file__).resolve().parent


def main():
    counts=json.loads((P/'evidence/final-counts.json').read_text())
    criteria=[]
    def row(key, target, actual, unit, evidence, status='충족', gap='', resume='추가 조사 불필요; 고정 근거를 재사용한다.', denominator=None):
        den=target if denominator is None else denominator
        criteria.append({'id':key,'planned':{'numerator':target,'denominator':den},'actual':{'numerator':actual,'denominator':den},'unit':unit,'evidence':evidence,'status':status,'gap':gap,'minimum_resume':resume})
    row('C01-governance-and-resume',6,6,'required input groups',['evidence/resume-context.json','evidence/inherited-inputs.json','PROGRESS.md'])
    row('C02-contract-and-dependency-retained',1,1,'original start contract',['manifest.json base_commit/dependencies','evidence/resume-context.json original_manifest_retained'])
    row('C03-fixed-component-releases',4,4,'components',['frame.csv rows2–5; component/version/release_url/source_sha/cutoff','streams/graph/versions.md','streams/android/metadata.json','streams/react/metadata.md'])
    row('C04-supported-environments-recorded',4,4,'components',['frame.csv support_environment/source_distribution_match'],'충족(환경 실행과 구별)','Graphviz binary, Android device and mounted React not executed.','Observed environment metadata is sufficient for this condition; real-device claims need separate runs.')
    row('C05-distribution-source-correspondence',4,3,'component byte/provenance mappings',['streams/graph/source-receipts.json','streams/android/evidence/source-match.json','streams/react/runtime-manifest.json','frame.csv GV'],'부분','Graphviz release/tag/contained source verified; no built native binary correspondence.','Acquire official14.1.1 binary/source build provenance if a runtime claim is needed.')
    row('C06-frame-normal-boundary',8,8,'retained case slots',['SCOPE.md input section','frame.csv normal_case/boundary_case','observations.csv rows2–9'])
    row('C07-first-eligible-use-issue',4,3,'bounded recruitment slots',['streams/graph/issue-selection.json','streams/react/issue-metadata.json','streams/android/issue-recruitment.json'],'부분','Android sorted release-window issue frame unconfirmed. D3/GV/RS firstness is bounded by preserved query; main-version requester output is unconfirmed in all4.','Obtain complete Android2024-04-09..2026-04-09 public roster, sort and read first eligible body; preserve other version gaps.')
    row('C08-attribution-classification',4,4,'separated attribution records',['transfer.csv T-D3/T-GV/T-AN/T-RS and four POST rows','RESULT.md Q2'],'충족','Classification is not four direct donor-paper adoptions.','Named primary citation/design record would change AN/RS or D3 historical attribution; keep current limited categories meanwhile.')
    row('C09-variable-assumption-code-mapping',4,4,'components',['transfer.csv T-*-POST','streams/final-audit/graph-review.json','streams/final-audit/animation-review.json'])
    row('C10-API-first-seal',8,8,'baseline rows',['predictions.csv view=API','evidence/commit-ledger.jsonl stage1b','evidence/prediction-seal.json baseline_commit'])
    row('C11-three-view-rows-sealed',24,24,'stored case-view rows',['predictions.csv','evidence/prediction-seal.json','evidence/comparison-rule.json'],'충족(결손 행 보존)','Stored rows include2 missing A treatments.','Do not backfill sealed A rows.')
    row('C12-added-treatment-availability',16,14,'A/B case-view additions',['streams/graph/a-windows.json GV-A','streams/android/a-window.json','streams/react/a-window.json','evidence/b-windows.json'],'부분','GV A missing2/16 additions. Total available views22=API8+A6+B8;14 added-window views.','Find official compatible worked sfdp setup for post-seal supplement; a fresh treatment effect needs a new preseal protocol.')
    row('C13-displayed-window-accounting',6,6,'unique nonmissing displayed windows',['streams/graph/a-windows.json','streams/android/a-window.json','streams/react/a-window.json','evidence/b-windows.json'],'충족','Six unique windows populate7 implementation-view slots because AN/RS B is shared; all recorded counts<=250. Full text deliberately not republished.','If recount required, retrieve exact version/section and verify stored display hash, do not overwrite recorded exposure.')
    row('C14-exposure-and-correction',1,1,'pre-outcome exposure protocol',['evidence/reader-amendment.md','streams/donor-reader/exposure.md','evidence/prediction-seal.json'],'충족','Curator and learned-knowledge exposure remains; no human randomization or independent participant sample.','For causal link-effect inference, preregister an independent reader/design protocol.')
    row('C15-observations-or-exact-breakpoint',8,8,'case records',['observations.csv rows2–9','streams/graph/transfer-notes.md'],'충족','GV rows name the public fixed-coordinate/one-step breakpoint rather than fabricate observations.','Only new relevant public contract/output can resolve these rows.')
    row('C16-upstream-test-output-search',4,4,'component scoped inventories',['streams/graph/test-inventory.json','streams/android/evidence/SpringTests.java','streams/react/observations.json original_output_search_scope','streams/final-audit/animation-review.md'],'충족','Scoped searches are not exhaustive proof of absence. Declarations and disabled tests are separated from retained output.','Exact matching upstream fixture or author archive needed to upgrade evidence.')
    row('C17-same-version-independent-original-output',8,0,'main case output matches',['observations.csv independent_original_same_version_input','evidence/final-counts.json independent_original_outputs_main_frame'],'미확인(확보 관측 0)','No matching independent archived output found in reviewed scope.','Acquire exact version/input/schedule original trace with author/run key; local reruns cannot replace historical provenance.')
    row('C18-auxiliary-main-runs',8,6,'main case rows with researcher output',['streams/graph/d3-run.json D3-N/B','streams/android/evidence/probe-output.csv AN-N/B','streams/react/raw-outputs.json RS-N/B'],'부분(보조)','GV2 unexecuted; Android platform stubs and raw SpringValue are not real UI environments.','Only run additional paths if required by a concrete claim; keep each future run in a new receipt.')
    row('C19-counterexamples-both-families',2,2,'families',['RESULT.md Q6','streams/graph/findings.md','streams/android/findings.md','streams/react/findings.md'])
    row('C20-primary-distinct-works',20,counts['eligible_unique_primary_works'],'unique external primary works (attainment target, not a rate)',['sources.jsonl work_id/count_eligible','streams/final-audit/source-audit.json eligible_works','evidence/final-counts.json'])
    for key,target,unit in [('component_lineage',4,'component works'),('independent_issue_or_design',4,'independent issue/design works'),('original_source_astronomy',2,'astronomy original works'),('original_source_oscillator',2,'oscillator original works'),('independent_output_study',4,'independent original output/experimental works'),('additional_boundary_or_accessibility',4,'other explanatory/boundary works')]:
        row('C21-'+key,target,counts['disjoint_allocation'][key]['count'],unit,['streams/final-audit/source-audit.json disjoint_allocation.'+key,'evidence/final-counts.json disjoint_allocation.'+key],'충족','All allocations disjoint; output-study quota is not main-case original-output coverage.','Reuse allocated work IDs; do not count mirrors/tests as new works.')
    row('C22-primary1986-body',1,0,'cited historical paper full body',['streams/donors/search-log.jsonl','evidence/reader-amendment.md'],'미확인(접근 결손)','Barnes&Hut1986 body unavailable through attempted routes; metadata/intermediary excluded from minimum primary-body count.','Obtain legal author/public archive body at DOI10.1038/324446a0; verify relevant algorithm and conditions. Do not retroactively change B.')
    row('C23-source-ledger-and-failure-paths',counts['canonical_source_records'],counts['canonical_source_records'],'canonical acquisition records',['sources.jsonl source_id/acquisition_refs/canonical_cases','search-log.jsonl','evidence/final-counts.json'],'충족','164 records are31 eligible works, not164 independent works. Failed/snippet/metadata-only donor bodies are excluded.','Preserve source lineage and original fields when adding acquisitions.')
    row('C24-return-cards-stakeholder-conditions',16,16,'four stakeholder conditions per four cards',['cards.md D3/GV/AN/RS four stakeholder tables'],'충족','Conditional design recommendations; no measured card benefit.','Actual user priorities may change first link.')
    row('C25-first-two-tables-and-final-three',3,3,'required tables',['RESULT.md first8row table, second4row table, final3row weakness table'])
    row('C26-Q-answers-and-falsification',7,7,'questions',['RESULT.md Q1–Q7','SELF_CHECK.md Q1–Q7'],'충족','Answers include unconfirmed/failed searches instead of treating all questions as empirically resolved.','Each question names smallest contrary evidence and next action.')
    row('C27-different-prediction-denominator',0,0,'presealed differing case rows',['evidence/comparison-rule.json','evidence/final-counts.json'],'해당 없음(조건부 적중률)','A/B operational difference observed0/6; difference-only denominator0, so no conditional accuracy rate.','A new protocol needs different prior operational forecasts, matched independent output and donor support.',denominator=0)
    row('C28-link-caused-human-action-effect',None,None,'human design experiment',['RESULT.md Q7','cards.md','SELF_CHECK.md Q7'],'미실시','Historical issue-author actions and studies are not participants in this link-effect experiment.','Obtain actual before/after designer choice and outcome; do not infer causal effect from equation similarity.',denominator=None)
    row('C29-review-corrections',6,6,'report reviewer requested corrections',['streams/final-audit/report-review.json','streams/final-audit/graph-review.json','streams/final-audit/animation-review.json'],'충족','Historical wrong D3 anchor and two CRLF digest entries retained with correction evidence.','No further broad rerun needed; check final bytes and links.')
    row('C30-structural-and-link-audit',1,0,'final artifact audit',['evidence/audit-final.json'],'검사 예정','Generator sets this to actual receipt after successful audit.','Run python -B docs/workstreams/research/AF-RES-061/audit_final.py and record actual checked SHA.')
    row('C31-session-check-fetch',1,0,'Git contract/ownership check',['manifest.json','evidence/session-check-stage4.json'],'검사 예정','No new check claimed by this generator.','Run python -B -m workbench.session check docs/workstreams/research/AF-RES-061/manifest.json --fetch on committed result; store stdout/stderr/exit/actor.')
    row('C32-fixed-result-remote-readback',2,0,'fixed RESULT and acceptance files',['evidence/fixed-result-verification.json'],'검사 예정','Remote fixed result readback happens after result commit.','Read both files at exact result SHA and compare blob/bytes before writing HANDOFF.')
    a={'schema':'AF-RES-061.acceptance.v1','generated_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'executor':'/root synthesis with same-model graph/animation/source/report reviewers','overall_status':'부분 인계','status_reason':'Research and reporting preserve8slots,31primaryworks and all result gaps. Missing GV treatment/public-step input, Android complete first-issue recruitment,1986 body access and original-output provenance prevent full acceptance.','result_body_commit':'resolved in final HANDOFF after remote publication; no self-referential SHA invented','prior_result_commit':'672366cdf4542d4ca9f579963d66c2745f4316ed','prediction_seal':'02359364000057f69b00594d8b43571ac72df298','value_vocabulary':{'미확인':'fact/output not established','관측 0':'counted zero within stated scope','해당 없음':'undefined or inapplicable denominator/rate','미실시':'check or experiment not performed'},'criteria':criteria,'denominators':counts,'requirements_not_met_are_not_silent_passes':True,'final_closure_rule':'After commit, record actual check/readback receipts. Final HANDOFF-only commit cites the receipt-inclusive fixed result and performs final readback/check; pending generator entries must be resolved or honestly blocked.'}
    for criterion in criteria:
        key=criterion['id']
        if key=='C30-structural-and-link-audit' and (P/'evidence/audit-final.json').exists():
            audit=json.loads((P/'evidence/audit-final.json').read_text())
            if not audit['failed']:
                criterion.update(actual={'numerator':1,'denominator':1},status='충족',gap='Artifact audit only; not truth/runtime verification.',minimum_resume='No repeat unless an audit-covered artifact changes.')
                criterion['observed_receipt']={'checkout_sha':audit['checkout_sha'],'checked_utc':audit['checked_utc'],'passed':audit['passed'],'total':audit['total']}
        if key=='C31-session-check-fetch' and (P/'evidence/session-check-stage4.json').exists():
            receipt=json.loads((P/'evidence/session-check-stage4.json').read_text())
            if receipt.get('exit_code')==0:
                criterion.update(actual={'numerator':1,'denominator':1},status='충족',gap='Receipt checks the cited commit; subsequent HANDOFF is not retroactively included.',minimum_resume='Run again on final receipt-inclusive result before HANDOFF, preserving exact SHA and scope.')
                criterion['observed_receipt']={'checked_sha':receipt['checked_sha'],'exit_code':receipt['exit_code'],'actor':receipt['actor']}
        if key=='C32-fixed-result-remote-readback' and (P/'evidence/fixed-result-verification.json').exists():
            receipt=json.loads((P/'evidence/fixed-result-verification.json').read_text())
            matched=sum(bool(x.get('exact_blob_match')) for x in receipt['files'])
            criterion.update(actual={'numerator':matched,'denominator':2},status='충족' if matched==2 else '부분',gap='Readback covers receipt.result_commit; final HANDOFF separately names final receipt-inclusive fixed result.',minimum_resume='Final readback must precede HANDOFF; do not claim subsequent docs were in earlier check.')
            criterion['observed_receipt']={'result_commit':receipt['result_commit'],'matched_files':matched}
    (P/'evidence/acceptance-evidence.json').write_text(json.dumps(a,ensure_ascii=False,indent=2)+'\n')
    print(json.dumps({'criteria':len(criteria),'overall_status':a['overall_status'],'pending':[x['id'] for x in criteria if x['status']=='검사 예정']},ensure_ascii=False))


if __name__=='__main__':main()
